INSERT INTO streamer_info (jp_name, en_name, group_affiliation, generation_affiliation, gender, main_platform, has_twitch, has_youtube, twitch_channel_id, youtube_channel_id, lang)
SELECT seed.jp_name, seed.en_name, seed.group_affiliation, seed.generation_affiliation,
       seed.gender::gender_type, seed.main_platform::platform_type,
       seed.has_twitch, seed.has_youtube, seed.twitch_channel_id, seed.youtube_channel_id, seed.lang
FROM seed
WHERE NOT EXISTS (
  SELECT 1
  FROM streamer_info AS existing
  WHERE existing.youtube_channel_id = seed.youtube_channel_id
     OR (seed.twitch_channel_id IS NOT NULL
         AND existing.twitch_channel_id = seed.twitch_channel_id)
);

COMMIT;
